"""Semantic stages are generated by numerical execution, not static text."""
import unittest
from solver import simulate


class SemanticTraceTest(unittest.TestCase):
    def test_trace_has_real_rk2_stages_and_residuals(self):
        result = simulate(grid=16, until=0.0002, dt=0.0001, shear=True, trace=True)
        trace = result["semantic_trace"]
        self.assertEqual(len(trace), 1 + 3 * result["steps"])
        self.assertEqual([x["operation"] for x in trace[:4]],
                         ["pressure_projection", "momentum_rhs",
                          "pressure_projection", "rk2_projection"])
        for entry in trace:
            self.assertTrue(entry["meaning"])
            self.assertTrue(entry["diagnostic"])
        self.assertLess(trace[-1]["diagnostic"]["max_divergence"], 1e-9)

    def test_trace_opt_in(self):
        self.assertNotIn("semantic_trace", simulate(grid=16, until=0.0001))


if __name__ == "__main__":
    unittest.main()
